import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import Navbar from "./components/Navbar";
import UserDashboard from "./pages/UserDashboard";
import AdminDashboard from "./pages/AdminDashboard";
import Analytics from "./pages/Analytics";
import Logs from "./pages/Logs";
import LoginForm from "./components/LoginForm";

function App() {
  const [isAdmin, setIsAdmin] = useState(false); // admin login state

  return (
    <Router>
      <Navbar role={isAdmin ? "admin" : "user"} />
      <Routes>
        {/* Public user dashboard */}
        <Route path="/" element={<UserDashboard />} />

        {/* Admin login page */}
        <Route path="/admin/login" element={<LoginForm setAdmin={setIsAdmin} />} />

        {/* Protected admin routes */}
        <Route path="/admin/dashboard" element={isAdmin ? <AdminDashboard /> : <Navigate to="/admin/login" />} />
        <Route path="/admin/logs" element={isAdmin ? <Logs /> : <Navigate to="/admin/login" />} />
        <Route path="/admin/analytics" element={isAdmin ? <Analytics /> : <Navigate to="/admin/login" />} />
      </Routes>
    </Router>
  );
}

export default App;
